-- =====================================================================
--  Genba Memory — demo seed  (DDS-15 section 9; TEST-15 TC-005)
--  Reproduces SRS-15 Appendix A and AC-01…AC-09 through the real functions and triggers.
--  Generated by seed15.py, which also re-derives every expected value with the Python twins;
--  PostgreSQL itself was not executed on the authoring machine (README-15 "Verification").
--  The 16 probes at the end must each FAIL inside their transaction.
--
--  Appendix A  a Thai symptom query with scope machine = M-07 returns #418 (0.870, verified,
--              Japanese 8D), #602 (0.740, verified, one recurrence) and #331 (0.610, extracted,
--              cause not recorded — a knowledge gap). #418 has the LOWEST BM25 score of the
--              three and still ranks first: the Japanese report is reachable through the vector
--              leg and the entity match, which is AC-03 in one row.
--  AC-04/07    quality case QC-2026-0912 opens on 2026-09-21 → suggestion in 1.9 s → recurrence
--              of #418 at 0.870 after 25 whole months, unconfirmed until a person confirms it.
--  AC-05       complaint_customer_2026-03.pdf is min_role manager + group quality_restricted:
--              the engineer's query returns two rows and reports one ACL-filtered; the curator's
--              returns three. The row never appears, not even as a snippet.
--  AC-06       an engineer flags #710's cause as incorrect → the field is suppressed and queued.
--  AC-08       every result row carries its source document; #419 was merged into #418 and its
--              document moved rather than being dropped.
--  AC-09       bge-m3@2 is registered and half the chunks re-embedded with search still served
--              from bge-m3@1.
--  AC-01/02    a 12-document labelled set (0.875 narrative / 0.958 factual) and a 12-query
--              evaluation set (run A 0.833 / 0.632 passes, run B 0.667 / 0.413 does not).
-- =====================================================================
SET TIME ZONE 'Asia/Bangkok';
BEGIN;

-- --- platform master data -------------------------------------------





-- --- settings: the locked ones are constraints, not preferences ------

-- --- ranking weights: FR-18 as five numbers that sum to 1.000 --------





-- --- the deterministic half of the classifier (FR-08) ---------------

-- --- entity map: M07, M-07 and 7号機 are one machine (FR-10) --------

-- --- documents: the originals, immutable and always linked (C-01) ---

-- --- ingestion jobs, including the two that failed and the duplicate



-- --- the scanned Japanese 8D: OCR pages and regions (FR-02, IF-76) --


-- --- the near-duplicate: the same 8D as DOCX (FR-04) ---------------

-- --- the embedding registry and a re-embed running under live search


-- --- chunks: four of the Japanese 8D, and the chat export that tries
--     to give the system instructions (AI-08, P-6) --------------------

-- --- extraction runs: model, prompt and schema version (NFR-08) -----

-- --- case records: the structure, never a replacement for the source


-- --- one memory.case_field row per field, each with its own
--     confidence and provenance (ADR-H03, FR-13) ---------------------

-- --- entities and symptom descriptors (FR-10, FR-11) ----------------


-- --- the lexical index: BM25 needs df and avgdl as rows (ADR-H04) ---

-- term_stat carries every term of the twelve indexed cases; the
-- generator writes it from the same tokenizer memory.tokenize() implements.


-- --- the duplicate case merged into #418; its document moved, not lost

UPDATE knowledge.case_source SET case_record_id = '00000000-0000-7000-8000-000000006418'
  WHERE case_record_id = '00000000-0000-7000-8000-000000006419';

-- --- verification: the one audited path into established fact -------

-- --- the new case that opens on 2026-09-21 (FR-20, AC-04) -----------


UPDATE knowledge.case_record SET quality_case_id = '00000000-0000-7000-8000-000000009002' WHERE id = '00000000-0000-7000-8000-000000006733';

-- --- the retrievals. query_candidate carries what SQL cannot compute
--     (the ANN rank and the cross-encoder similarity); everything after
--     it is memory.rank_query() and is re-derived in Python -----------




-- --- recurrence: detected by the same ranking, confirmed by a person

-- --- feedback, and the flag that suppresses a field (AC-06, FR-30) --

-- --- curation decisions -------------------------------------------
UPDATE memory.curation_item
   SET state = 'resolved', decided_by = '00000000-0000-7000-8000-000000001005', decided_at = '2026-09-20 09:30', decision = 'merged'
 WHERE kind = 'near_duplicate';

UPDATE memory.curation_item
   SET state = 'in_review', decided_by = NULL
 WHERE kind = 'low_confidence'
   AND case_record_id = '00000000-0000-7000-8000-000000006688';

-- --- the labelled set (AI-02, AC-01) and the evaluation set (AI-04)







-- --- audit trail for the decisions above ---------------------------


COMMIT;

-- =====================================================================
-- EXPECTED VALUES (DDS-15 section 9; re-derived in Python — TEST-15 TC-005)
-- =====================================================================
\echo '=== Appendix A — the three ranked cases (AC-03, AC-08, FR-19) ==='
SELECT r.rank, cr.title, r.final_score, r.lex_score, r.lex_rank, r.vec_rank, r.rerank_sim,
       r.entity_overlap, r.recency_weight, r.outcome_weight, r.verified,
       r.why_json -> 'badge' AS badge
  FROM memory.query_result r JOIN knowledge.case_record cr ON cr.id = r.case_record_id
 WHERE r.query_id = '00000000-0000-7000-8000-000000007001' ORDER BY r.rank;
\echo 'expected: 1 #418 0.870 (lex 1.1323 rank 6, vec 1, sim 0.8342, ent 1.000, rec 0.556, out 1.000, verified) | 2 #602 0.740 | 3 #331 0.610 badge extracted_not_verified'
\echo '=== AC-03: the Japanese 8D has the LOWEST BM25 of the three and still ranks first ==='
SELECT cr.title, r.lex_score, r.lex_rank, r.vec_rank, ci.lang
  FROM memory.query_result r JOIN knowledge.case_record cr ON cr.id = r.case_record_id
  JOIN memory.case_index ci ON ci.case_record_id = r.case_record_id
 WHERE r.query_id = '00000000-0000-7000-8000-000000007001' ORDER BY r.lex_score;
\echo 'expected: #418 1.1323 (lex rank 6, vec rank 1, index lang ja) below #602 12.6645 and #331 16.9755'
\echo '=== C-03: the same query with the verified-only default ==='
SELECT r.rank, cr.title, r.final_score FROM memory.query_result r
  JOIN knowledge.case_record cr ON cr.id = r.case_record_id
 WHERE r.query_id = '00000000-0000-7000-8000-000000007002' ORDER BY r.rank;
\echo 'expected: 1 #418 | 2 #602 | 3 #655 — #331 is absent, #655 takes third place at 0.598'
\echo '=== AC-05: the restricted complaint, as an engineer and as a curator ==='
SELECT l.user_role, l.n_results, l.n_acl_filtered,
       (SELECT count(*) FROM memory.query_result r WHERE r.query_id = l.id
          AND r.case_record_id = '00000000-0000-7000-8000-000000006688') AS complaint_rows
  FROM memory.query_log l WHERE l.id IN ('00000000-0000-7000-8000-000000007004', '00000000-0000-7000-8000-000000007005') ORDER BY l.user_role;
\echo 'expected: engineer 2 results, 1 acl-filtered, 0 complaint rows; curator 3 results, 0 filtered, 1 complaint row'
\echo '=== AC-04 / AC-07: the suggestion and the recurrence ==='
SELECT s.latency_ms, prior.title, r.score, r.interval_months, r.confirmed_at IS NULL AS awaiting_confirmation
  FROM memory.suggestion s, memory.recurrence r
  JOIN knowledge.case_record prior ON prior.id = r.prior_case_id
 WHERE s.quality_case_id = '00000000-0000-7000-8000-000000009002' AND r.case_record_id = '00000000-0000-7000-8000-000000006733';
\echo 'expected: 1912 ms, #418, 0.870, 25 months, awaiting confirmation true'
\echo '=== AC-06: the flagged cause is suppressed from the card ==='
SELECT cf.field, cf.flagged, cf.flagged_reason, v.cause_text
  FROM memory.case_field cf JOIN memory.v_case_card v ON v.case_record_id = cf.case_record_id
 WHERE cf.case_record_id = '00000000-0000-7000-8000-000000006710' AND cf.field = 'cause';
\echo 'expected: cause, true, The belt was fine; the specks came from the upstream washer., cause_text NULL'
\echo '=== AI-08: the chat export that tried to give instructions ==='
SELECT c.suspicious, c.suspicious_reason, ci.kind
  FROM knowledge.chunk c LEFT JOIN memory.curation_item ci ON ci.chunk_id = c.id
 WHERE c.id = '00000000-0000-7000-8000-000000008405';
\echo 'expected: true, instruction-like text in an ingested document (SRS-15 AI-08), suspicious_chunk'
\echo '=== FR-26 / FR-31: knowledge gaps and coverage ==='
SELECT * FROM memory.knowledge_gaps();
SELECT memory.coverage_metrics();
\echo 'expected: 4 cases in the gap list (#331 cause+verification, #688 verification, #710 verification, #733 cause+verification); coverage over 13 case records (the merged #419 is still a row)'
\echo '=== AI-04 / AI-02: the evaluation gate ==='
SELECT kind, model, recall_at_5, mrr, narrative_accuracy, factual_accuracy, passed, investigate
  FROM memory.v_eval_gate;
\echo 'expected: retrieval bge-m3@1 0.833 / 0.632 passed true; retrieval bge-m3@2 0.667 / 0.413 passed FALSE investigate true; extraction 0.875 / 0.958 passed true'
\echo '=== FR-23 / FR-24 / FR-25: recurring problems, effectiveness, MTBR ==='
SELECT * FROM memory.top_recurring('machine', '2022-01-01', '2026-12-31');
SELECT * FROM memory.action_effectiveness('overload');
SELECT memory.mtbr('overload');
\echo 'expected: M-04 2 cases 1 confirmed recurrence first, then M-07 4 cases 0 (the #733 link is still unconfirmed), M-09 1 / 0, M-12 1 / 0; action_effectiveness lists #275, #418, #602, #655 with recurred = true only for #602; MTBR 5.0 months'
\echo '=== AC-09: re-embedding under live search ==='
SELECT * FROM memory.v_embedding_status ORDER BY version;
\echo 'expected: bge-m3@1 active with the chunks, bge-m3@2 registering, job running 24/48, search_available true'
\echo '=== counts ==='
SELECT (SELECT count(*) FROM knowledge.document)      AS documents,
       (SELECT count(*) FROM knowledge.case_record)   AS cases,
       (SELECT count(*) FROM memory.case_field)       AS fields,
       (SELECT count(*) FROM memory.case_index)       AS indexed,
       (SELECT count(*) FROM memory.term_stat)        AS terms,
       (SELECT count(*) FROM memory.query_result)     AS results,
       (SELECT count(*) FROM memory.curation_item)    AS curation,
       (SELECT count(*) FROM memory.eval_result)      AS eval_results;
\echo 'expected: documents 16, cases 13, fields 41, indexed 12, terms 509, results 16, curation 7 (3 low confidence + 1 unmapped entity + 1 near-duplicate + 1 flagged field + 1 suspicious chunk), eval_results 120'

-- =====================================================================
-- PROBES — each must FAIL (TEST-15 TC-003). ON_ERROR_STOP is off so every probe runs.
-- =====================================================================
\set ON_ERROR_STOP off
\echo '--- P-01 change a document''s sha256 -> DOCUMENT_IMMUTABLE (C-01, FR-05)'
BEGIN; UPDATE knowledge.document SET sha256 = 'changed' WHERE id = '00000000-0000-7000-8000-000000005001'; ROLLBACK;
\echo '--- P-02 ingest the same sha256 twice -> document_sha256_key (FR-04)'
BEGIN; INSERT INTO knowledge.document (sha256, kind, uri, original_name) SELECT sha256, kind, 'x', 'x' FROM knowledge.document WHERE id = '00000000-0000-7000-8000-000000005001'; ROLLBACK;
\echo '--- P-03 a machine-written field without its extraction -> EXTRACTION_REQUIRED (NFR-08)'
BEGIN; INSERT INTO memory.case_field (case_record_id, field, value, confidence, provenance_json) VALUES ('00000000-0000-7000-8000-000000006418', 'containment', 'sorted stock', 0.9, '{"document_id": "00000000-0000-7000-8000-000000005001", "page": 1}'); ROLLBACK;
\echo '--- P-04 a machine-written field without provenance -> PROVENANCE_REQUIRED (C-01, FR-13)'
BEGIN; INSERT INTO memory.case_field (case_record_id, field, value, confidence, extraction_id) VALUES ('00000000-0000-7000-8000-000000006418', 'containment', 'sorted stock', 0.9, '00000000-0000-7000-8000-000000008505'); ROLLBACK;
\echo '--- P-05 verification by an engineer -> VERIFY_NEEDS_CURATOR (FR-28)'
BEGIN; INSERT INTO memory.verification (case_record_id, verified_by) VALUES ('00000000-0000-7000-8000-000000006710', '00000000-0000-7000-8000-000000001001'); ROLLBACK;
\echo '--- P-06 verify a case that has no source document -> SOURCE_REQUIRED (AI-07, AC-08)'
BEGIN; INSERT INTO knowledge.case_record (id, title, verified_by, verified_at) VALUES ('00000000-0000-7000-8000-000000099001', 'invented precedent', '00000000-0000-7000-8000-000000001005', now()); ROLLBACK;
\echo '--- P-07 verify a case that still has a flagged field -> FLAGGED_FIELD_PRESENT (FR-30)'
BEGIN; INSERT INTO memory.verification (case_record_id, verified_by) VALUES ('00000000-0000-7000-8000-000000006710', '00000000-0000-7000-8000-000000001005'); ROLLBACK;
\echo '--- P-08 un-flag a suppressed field without a curator -> UNFLAG_NEEDS_CURATOR (FR-27, AC-06)'
BEGIN; UPDATE memory.case_field SET flagged = false, corrected_by = '00000000-0000-7000-8000-000000001001' WHERE id = '00000000-0000-7000-8000-000000008634'; ROLLBACK;
\echo '--- P-09 claim an unmapped entity as canonical -> ENTITY_NOT_MAPPED (FR-10)'
BEGIN; INSERT INTO memory.case_entity (case_record_id, kind, raw_value, canonical_id, mapped) VALUES ('00000000-0000-7000-8000-000000006710', 'machine', 'CONV-2', 'M-99', true); ROLLBACK;
\echo '--- P-10 confirm a recurrence as a viewer -> CONFIRM_NEEDS_ENGINEER (AI-06, ADR-H07)'
BEGIN; UPDATE memory.recurrence SET confirmed_by = '00000000-0000-7000-8000-000000001004', confirmed_at = now() WHERE case_record_id = '00000000-0000-7000-8000-000000006733'; ROLLBACK;
\echo '--- P-11 index a case more permissively than its source -> ACL_WEAKER_THAN_SOURCE (C-05, AC-05)'
BEGIN; INSERT INTO memory.case_index (case_record_id, scope, lang, indexed_text, tokens, token_count, acl_json) VALUES ('00000000-0000-7000-8000-000000006688', 'case', 'en', 'x', ARRAY['x'], 1, '{"min_role": "viewer"}'); ROLLBACK;
\echo '--- P-12 store a vector without its model version -> EMBEDDING_VERSION_REQUIRED (AI-09)'
BEGIN; UPDATE knowledge.chunk SET embedding = array_fill(0.1::real, ARRAY[1024])::vector, embedding_version = NULL WHERE id = '00000000-0000-7000-8000-000000008401'; ROLLBACK;
\echo '--- P-13 retire a version a running re-embed still serves -> VERSION_IN_USE (AC-09)'
BEGIN; UPDATE memory.embedding_model SET state = 'retired' WHERE version = 'bge-m3@1'; ROLLBACK;
\echo '--- P-14 mark a failing evaluation run as passed -> EVAL_GATE (AI-02, AI-04)'
BEGIN; UPDATE memory.eval_run SET passed = true WHERE id = '00000000-0000-7000-8000-000000009402'; ROLLBACK;
\echo '--- P-15 break the ranking weights -> RANK_WEIGHTS_SUM (FR-18)'
BEGIN; UPDATE memory.rank_weight SET weight = 0.900 WHERE key = 'similarity'; ROLLBACK;
\echo '--- P-16 edit a retrieval log or a verification -> APPEND_ONLY (C-02, SEC-15 O-3)'
BEGIN; DELETE FROM memory.verification WHERE case_record_id = '00000000-0000-7000-8000-000000006418'; ROLLBACK;
\set ON_ERROR_STOP on
