INSERT INTO memory.setting (key, value, locked, description) VALUES
  ('verified_only_default', 'true'::jsonb, true, 'Retrieval returns human-verified cases unless the caller opts out; an unverified extraction is never an established fact (C-03).'),
  ('acl_at_query_time', 'true'::jsonb, true, 'The ACL is a predicate inside the retrieval CTEs (C-05, NFR-05, AC-05).'),
  ('local_only', 'true'::jsonb, true, 'No document content leaves the plant (C-04, NFR-06).'),
  ('source_link_required', 'true'::jsonb, true, 'Every result carries a retrievable original (C-01, AC-08).'),
  ('extraction_marked', 'true'::jsonb, true, 'Machine-written fields carry confidence, provenance and the extraction that made them (C-02).'),
  ('rerank_depth', '30'::jsonb, true, 'AI-05: the cross-encoder reranks the top 30 fused candidates.'),
  ('embedding_dim', '1024'::jsonb, true, 'knowledge.chunk.embedding is vector(1024) on the platform.'),
  ('recall_at_5_gate', '0.8'::jsonb, true, 'AI-04.'),
  ('mrr_gate', '0.6'::jsonb, true, 'AI-04.'),
  ('narrative_accuracy_gate', '0.85'::jsonb, true, 'AI-02.'),
  ('factual_accuracy_gate', '0.95'::jsonb, true, 'AI-02.'),
  ('recurrence_threshold', '0.72'::jsonb, false, 'AI-06: tuned for recall; every detection still needs human confirmation.'),
  ('near_duplicate_threshold', '0.92'::jsonb, false, 'FR-04.'),
  ('low_confidence_threshold', '0.7'::jsonb, false, 'FR-13, FR-27: below this a field goes to the curation queue.'),
  ('recency_halflife_days', '900'::jsonb, false, 'FR-18: a fix from two years ago is still worth reading.'),
  ('ocr_confidence_gate', '0.95'::jsonb, false, 'FR-02; the same gate GenbaGo uses (IF-76).'),
  ('rrf_k', '60'::jsonb, false, 'ADR-H04.'),
  ('retention_days_originals', '730'::jsonb, false, 'Records policy floor.'),
  ('retention_days_query_log', '365'::jsonb, false, 'Evaluation needs history.');
