INSERT INTO knowledge.case_record (id, title, opened_at, closed_at, scope_json, symptom_text, cause_text, action_text, verification_text, outcome, extracted_by) VALUES
  ('00000000-0000-7000-8000-000000006096', '#96 M-07 hydraulic pressure low after warm-up', '2022-05-14 08:00', '2022-05-27 08:00', '{"line": "L3", "machine": "M-07"}'::jsonb, 'Hydraulic pressure drops below set point after 40 minutes of running.', 'Relief valve seat worn.', 'Replaced relief valve; added to 12-month PM list.', 'Pressure stable for 8 weeks after replacement.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006178', '#178 L3 short shot on RAD-500-A after material change', '2023-07-02 08:00', '2023-07-20 08:00', '{"line": "L3"}'::jsonb, 'Short shot rate rose to 4.1 % after switching regrind supplier.', 'Regrind moisture above specification.', 'Re-dried material; added incoming moisture check to the receiving standard.', 'Short shot rate 0.4 % over the following month.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006275', '#275 M-12 overload trip during start-up', '2024-02-19 08:00', '2024-03-04 08:00', '{"line": "L1", "machine": "M-12"}'::jsonb, 'Overload trip on start-up, motor draws high current for 3 seconds.', 'Contactor contacts pitted.', 'Replaced contactor; added contact inspection to the 6-month PM list.', 'No trips in the following 6 months.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006331', '#331 Motor stop on M-07, no alarm recorded', '2023-12-11 08:00', '2023-12-11 08:00', '{"line": "L3", "machine": "M-07"}'::jsonb, 'Motor stop, no alarm recorded. Restarted by the night shift.', NULL, 'Reset and restart.', NULL, 'unknown', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006418', '#418 M-07 overload alarm, motor not rotating', '2024-08-21 08:00', '2024-08-28 08:00', '{"line": "L3", "machine": "M-07"}'::jsonb, 'Machine overload alarm, motor not rotating, intermittent.', 'Proximity sensor abnormal (drifting output when hot).', 'Replaced proximity sensor, added to 6-month PM list.', 'No recurrence for 14 months after replacement.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006506', '#506 L1 surface scratch on finished parts', '2025-02-10 08:00', '2025-02-21 08:00', '{"line": "L1"}'::jsonb, 'Scratch marks on 2 % of finished parts at the packing station.', 'Worn guide rail liner.', 'Replaced liner; added liner check to the weekly checklist.', 'Scratch rate 0.1 % over four weeks.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006602', '#602 M-04 overload trip after continuous running', '2025-06-03 08:00', '2025-06-17 08:00', '{"line": "L3", "machine": "M-04"}'::jsonb, 'Overload trip after 2 h of continuous running.', 'Coupling misalignment after mould change.', 'Realignment, added alignment check to the changeover checklist.', 'No trip for 5 months after realignment.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006655', '#655 M-04 overload trip again after changeover', '2025-11-18 08:00', '2025-12-02 08:00', '{"line": "L3", "machine": "M-04"}'::jsonb, 'Overload trip two hours after a mould change.', 'Alignment check in the changeover checklist was not performed.', 'Realignment; changeover checklist made a signed step.', 'No trip in the following 9 months.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006688', '#688 Customer complaint: dimension out of tolerance on RAD-500-A', '2026-03-05 08:00', NULL, '{"line": "L3"}'::jsonb, 'Customer reports fin pitch 3.5 mm against a 3.2 mm nominal on two lots.', 'Under investigation.', 'Containment sorting at the customer site.', NULL, 'not_resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006710', '#710 M-09 contamination on assembled units', '2026-08-12 08:00', '2026-08-19 08:00', '{"line": "L1", "machine": "M-09"}'::jsonb, 'Dark specks found on assembled units at final inspection.', 'Conveyor belt shedding.', 'Replaced belt.', NULL, 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006722', '#722 L3 flash on RAD-500-A after tool change', '2026-09-02 08:00', '2026-09-09 08:00', '{"line": "L3"}'::jsonb, 'Flash along the parting line after a tool change.', 'Clamp force set below the standard.', 'Restored clamp force; added the value to the setup sheet.', 'No flash in the following two weeks.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006733', '#733 M-07 overload, motor not rotating', '2026-09-21 08:00', NULL, '{"line": "L3", "machine": "M-07"}'::jsonb, 'Machine overload, motor not rotating, happens after the line warms up.', NULL, NULL, NULL, NULL, 'qwen2.5:7b-instruct-q4_K_M'),
  ('00000000-0000-7000-8000-000000006419', '#419 M-07 overload alarm, motor not rotating (from the DOCX copy)', '2024-08-21 08:00', '2024-08-28 08:00', '{"line": "L3", "machine": "M-07"}'::jsonb, 'Machine overload alarm, motor not rotating, intermittent.', 'Proximity sensor abnormal (drifting output when hot).', 'Replaced proximity sensor, added to 6-month PM list.', 'No recurrence for 14 months after replacement.', 'resolved', 'qwen2.5:7b-instruct-q4_K_M');
