INSERT INTO memory.case_index (case_record_id, scope, lang, indexed_text, tokens, token_count, embedding_version) VALUES
  ('00000000-0000-7000-8000-000000006096', 'case', 'th', 'M-07 hydraulic pressure low after warm-up Hydraulic pressure drops below set point after 40 minutes of running. Relief valve seat worn. Replaced relief valve; added to 12-month PM list. M-07 แรงดันไฮดรอลิคตกหลังเดินเครื่อง 40 นาที ลิ้นระบายสึก', ARRAY['m-07', 'hydraulic', 'pressure', 'low', 'after', 'warm-up', 'hydraulic', 'pressure', 'drops', 'below', 'set', 'point', 'after', '40', 'minutes', 'of', 'running', 'relief', 'valve', 'seat', 'worn', 'replaced', 'relief', 'valve', 'added', 'to', '12-month', 'pm', 'list', 'm-07', '40', 'แร', 'รง', 'งด', 'ดั', 'ัน', 'นไ', 'ไฮ', 'ฮด', 'ดร', 'รอ', 'อล', 'ลิ', 'ิค', 'คต', 'ตก', 'กห', 'หล', 'ลั', 'ัง', 'งเ', 'เด', 'ดิ', 'ิน', 'นเ', 'เค', 'คร', 'รื', 'ื่', '่อ', 'อง', 'นา', 'าท', 'ที', 'ลิ', 'ิ้', '้น', 'นร', 'ระ', 'ะบ', 'บา', 'าย', 'ยส', 'สึ', 'ึก']::text[], 75, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006178', 'case', 'ja', 'L3 short shot on RAD-500-A after material change Short shot rate rose to 4.1 % after switching regrind supplier. Regrind moisture above specification. Re-dried material; added incoming moisture check to the receiving standard. L3 RAD-500-A 材料変更後にショートショット率が4.1%に上昇。再生材の水分が規格外。', ARRAY['l3', 'short', 'shot', 'on', 'rad-500-a', 'after', 'material', 'change', 'short', 'shot', 'rate', 'rose', 'to', 'after', 'switching', 'regrind', 'supplier', 'regrind', 'moisture', 'above', 'specification', 're-dried', 'material', 'added', 'incoming', 'moisture', 'check', 'to', 'the', 'receiving', 'standard', 'l3', 'rad-500-a', '材料', '料変', '変更', '更後', '後に', 'にシ', 'ショ', 'ョー', 'ート', 'トシ', 'ショ', 'ョッ', 'ット', 'ト率', '率が', 'に上', '上昇', '再生', '生材', '材の', 'の水', '水分', '分が', 'が規', '規格', '格外']::text[], 59, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006275', 'case', 'ja', 'M-12 overload trip during start-up Overload trip on start-up, motor draws high current for 3 seconds. Contactor contacts pitted. Replaced contactor; added contact inspection to the 6-month PM list. M-12 起動時に過負荷トリップ。AL-214。電磁接触器の接点荒れ。接触器を交換。', ARRAY['m-12', 'overload', 'trip', 'during', 'start-up', 'overload', 'trip', 'on', 'start-up', 'motor', 'draws', 'high', 'current', 'for', 'seconds', 'contactor', 'contacts', 'pitted', 'replaced', 'contactor', 'added', 'contact', 'inspection', 'to', 'the', '6-month', 'pm', 'list', 'm-12', 'al-214', '起動', '動時', '時に', 'に過', '過負', '負荷', '荷ト', 'トリ', 'リッ', 'ップ', '電磁', '磁接', '接触', '触器', '器の', 'の接', '接点', '点荒', '荒れ', '接触', '触器', '器を', 'を交', '交換']::text[], 54, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006331', 'case', 'th', 'Motor stop on M-07, no alarm recorded Motor stop, no alarm recorded. Restarted by the night shift. Reset and restart. M-07 มอเตอร์หยุด ไม่มีอลาร์มบันทึกไว้ กะกลางคืนรีสตาร์ทเครื่อง', ARRAY['motor', 'stop', 'on', 'm-07', 'no', 'alarm', 'recorded', 'motor', 'stop', 'no', 'alarm', 'recorded', 'restarted', 'by', 'the', 'night', 'shift', 'reset', 'and', 'restart', 'm-07', 'มอ', 'อเ', 'เต', 'ตอ', 'อร', 'ร์', '์ห', 'หย', 'ยุ', 'ุด', 'ไม', 'ม่', '่ม', 'มี', 'ีอ', 'อล', 'ลา', 'าร', 'ร์', '์ม', 'มบ', 'บั', 'ัน', 'นท', 'ทึ', 'ึก', 'กไ', 'ไว', 'ว้', 'กะ', 'ะก', 'กล', 'ลา', 'าง', 'งค', 'คื', 'ืน', 'นร', 'รี', 'ีส', 'สต', 'ตา', 'าร', 'ร์', '์ท', 'ทเ', 'เค', 'คร', 'รื', 'ื่', '่อ', 'อง']::text[], 73, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006418', 'case', 'ja', 'M-07 overload alarm, motor not rotating Machine overload alarm, motor not rotating, intermittent. Proximity sensor abnormal (drifting output when hot). Replaced proximity sensor, added to 6-month PM list. M-07 過負荷アラーム、モーターが回転しない、断続的に発生。AL-102。近接センサー異常（高温時に出力ドリフト）。近接センサーを交換し、6か月点検リストに追加。', ARRAY['m-07', 'overload', 'alarm', 'motor', 'not', 'rotating', 'machine', 'overload', 'alarm', 'motor', 'not', 'rotating', 'intermittent', 'proximity', 'sensor', 'abnormal', 'drifting', 'output', 'when', 'hot', 'replaced', 'proximity', 'sensor', 'added', 'to', '6-month', 'pm', 'list', 'm-07', 'al-102', '過負', '負荷', '荷ア', 'アラ', 'ラー', 'ーム', 'モー', 'ータ', 'ター', 'ーが', 'が回', '回転', '転し', 'しな', 'ない', '断続', '続的', '的に', 'に発', '発生', '近接', '接セ', 'セン', 'ンサ', 'サー', 'ー異', '異常', '高温', '温時', '時に', 'に出', '出力', '力ド', 'ドリ', 'リフ', 'フト', '近接', '接セ', 'セン', 'ンサ', 'サー', 'ーを', 'を交', '交換', '換し', 'か月', '月点', '点検', '検リ', 'リス', 'スト', 'トに', 'に追', '追加']::text[], 84, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006506', 'case', 'th', 'L1 surface scratch on finished parts Scratch marks on 2 % of finished parts at the packing station. Worn guide rail liner. Replaced liner; added liner check to the weekly checklist. L1 รอยขีดข่วนบนชิ้นงานสำเร็จรูปที่สถานีแพ็ค รางไกด์สึก', ARRAY['l1', 'surface', 'scratch', 'on', 'finished', 'parts', 'scratch', 'marks', 'on', 'of', 'finished', 'parts', 'at', 'the', 'packing', 'station', 'worn', 'guide', 'rail', 'liner', 'replaced', 'liner', 'added', 'liner', 'check', 'to', 'the', 'weekly', 'checklist', 'l1', 'รอ', 'อย', 'ยข', 'ขี', 'ีด', 'ดข', 'ข่', '่ว', 'วน', 'นบ', 'บน', 'นช', 'ชิ', 'ิ้', '้น', 'นง', 'งา', 'าน', 'นส', 'สำ', 'ำเ', 'เร', 'ร็', '็จ', 'จร', 'รู', 'ูป', 'ปท', 'ที', 'ี่', '่ส', 'สถ', 'ถา', 'าน', 'นี', 'ีแ', 'แพ', 'พ็', '็ค', 'รา', 'าง', 'งไ', 'ไก', 'กด', 'ด์', '์ส', 'สึ', 'ึก']::text[], 78, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006602', 'case', 'th', 'M-04 overload trip after continuous running Overload trip after 2 h of continuous running. Coupling misalignment after mould change. Realignment, added alignment check to the changeover checklist. M-04 โอเวอร์โหลดทริปหลังเดินเครื่องต่อเนื่อง 2 ชั่วโมง AL-102 คัปปลิ้งไม่ตรงแนวหลังเปลี่ยนโมลด์', ARRAY['m-04', 'overload', 'trip', 'after', 'continuous', 'running', 'overload', 'trip', 'after', 'of', 'continuous', 'running', 'coupling', 'misalignment', 'after', 'mould', 'change', 'realignment', 'added', 'alignment', 'check', 'to', 'the', 'changeover', 'checklist', 'm-04', 'al-102', 'โอ', 'อเ', 'เว', 'วอ', 'อร', 'ร์', '์โ', 'โห', 'หล', 'ลด', 'ดท', 'ทร', 'ริ', 'ิป', 'ปห', 'หล', 'ลั', 'ัง', 'งเ', 'เด', 'ดิ', 'ิน', 'นเ', 'เค', 'คร', 'รื', 'ื่', '่อ', 'อง', 'งต', 'ต่', '่อ', 'อเ', 'เน', 'นื', 'ื่', '่อ', 'อง', 'ชั', 'ั่', '่ว', 'วโ', 'โม', 'มง', 'คั', 'ัป', 'ปป', 'ปล', 'ลิ', 'ิ้', '้ง', 'งไ', 'ไม', 'ม่', '่ต', 'ตร', 'รง', 'งแ', 'แน', 'นว', 'วห', 'หล', 'ลั', 'ัง', 'งเ', 'เป', 'ปล', 'ลี', 'ี่', '่ย', 'ยน', 'นโ', 'โม', 'มล', 'ลด', 'ด์']::text[], 103, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006655', 'case', 'th', 'M-04 overload trip again after changeover Overload trip two hours after a mould change. Alignment check in the changeover checklist was not performed. Realignment; changeover checklist made a signed step. M-04 โอเวอร์โหลดทริปอีกครั้งหลังเปลี่ยนโมลด์ AL-102 ไม่ได้ทำเช็คลิสต์ตรวจแนวเพลา', ARRAY['m-04', 'overload', 'trip', 'again', 'after', 'changeover', 'overload', 'trip', 'two', 'hours', 'after', 'mould', 'change', 'alignment', 'check', 'in', 'the', 'changeover', 'checklist', 'was', 'not', 'performed', 'realignment', 'changeover', 'checklist', 'made', 'signed', 'step', 'm-04', 'al-102', 'โอ', 'อเ', 'เว', 'วอ', 'อร', 'ร์', '์โ', 'โห', 'หล', 'ลด', 'ดท', 'ทร', 'ริ', 'ิป', 'ปอ', 'อี', 'ีก', 'กค', 'คร', 'รั', 'ั้', '้ง', 'งห', 'หล', 'ลั', 'ัง', 'งเ', 'เป', 'ปล', 'ลี', 'ี่', '่ย', 'ยน', 'นโ', 'โม', 'มล', 'ลด', 'ด์', 'ไม', 'ม่', '่ไ', 'ได', 'ด้', '้ท', 'ทำ', 'ำเ', 'เช', 'ช็', '็ค', 'คล', 'ลิ', 'ิส', 'สต', 'ต์', '์ต', 'ตร', 'รว', 'วจ', 'จแ', 'แน', 'นว', 'วเ', 'เพ', 'พล', 'ลา']::text[], 95, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006688', 'case', 'en', 'Customer complaint: dimension out of tolerance on RAD-500-A Customer reports fin pitch 3.5 mm against a 3.2 mm nominal on two lots. Under investigation. Containment sorting at the customer site. Customer reports fin pitch 3.5 mm against a 3.2 mm nominal on lots LOT-2603-118 and LOT-2603-119.', ARRAY['customer', 'complaint', 'dimension', 'out', 'of', 'tolerance', 'on', 'rad-500-a', 'customer', 'reports', 'fin', 'pitch', 'mm', 'against', 'mm', 'nominal', 'on', 'two', 'lots', 'under', 'investigation', 'containment', 'sorting', 'at', 'the', 'customer', 'site', 'customer', 'reports', 'fin', 'pitch', 'mm', 'against', 'mm', 'nominal', 'on', 'lots', 'lot-2603-118', 'and', 'lot-2603-119']::text[], 40, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006710', 'case', 'th', 'M-09 contamination on assembled units Dark specks found on assembled units at final inspection. Conveyor belt shedding. Replaced belt. M-09 พบจุดดำบนชิ้นงานประกอบที่การตรวจขั้นสุดท้าย สายพานลำเลียงหลุดลุ่ย', ARRAY['m-09', 'contamination', 'on', 'assembled', 'units', 'dark', 'specks', 'found', 'on', 'assembled', 'units', 'at', 'final', 'inspection', 'conveyor', 'belt', 'shedding', 'replaced', 'belt', 'm-09', 'พบ', 'บจ', 'จุ', 'ุด', 'ดด', 'ดำ', 'ำบ', 'บน', 'นช', 'ชิ', 'ิ้', '้น', 'นง', 'งา', 'าน', 'นป', 'ปร', 'ระ', 'ะก', 'กอ', 'อบ', 'บท', 'ที', 'ี่', '่ก', 'กา', 'าร', 'รต', 'ตร', 'รว', 'วจ', 'จข', 'ขั', 'ั้', '้น', 'นส', 'สุ', 'ุด', 'ดท', 'ท้', '้า', 'าย', 'สา', 'าย', 'ยพ', 'พา', 'าน', 'นล', 'ลำ', 'ำเ', 'เล', 'ลี', 'ีย', 'ยง', 'งห', 'หล', 'ลุ', 'ุด', 'ดล', 'ลุ', 'ุ่', '่ย']::text[], 82, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006722', 'case', 'ja', 'L3 flash on RAD-500-A after tool change Flash along the parting line after a tool change. Clamp force set below the standard. Restored clamp force; added the value to the setup sheet. L3 金型交換後にパーティングラインにバリ。型締力が標準以下に設定されていた。', ARRAY['l3', 'flash', 'on', 'rad-500-a', 'after', 'tool', 'change', 'flash', 'along', 'the', 'parting', 'line', 'after', 'tool', 'change', 'clamp', 'force', 'set', 'below', 'the', 'standard', 'restored', 'clamp', 'force', 'added', 'the', 'value', 'to', 'the', 'setup', 'sheet', 'l3', '金型', '型交', '交換', '換後', '後に', 'にパ', 'パー', 'ーテ', 'ティ', 'ィン', 'ング', 'グラ', 'ライ', 'イン', 'ンに', 'にバ', 'バリ', '型締', '締力', '力が', 'が標', '標準', '準以', '以下', '下に', 'に設', '設定', '定さ', 'され', 'れて', 'てい', 'いた']::text[], 64, 'bge-m3@1'),
  ('00000000-0000-7000-8000-000000006733', 'case', 'th', 'M-07 overload, motor not rotating Machine overload, motor not rotating, happens after the line warms up. M-07 โอเวอร์โหลด มอเตอร์ไม่หมุน เกิดหลังไลน์อุ่นเครื่อง AL-102', ARRAY['m-07', 'overload', 'motor', 'not', 'rotating', 'machine', 'overload', 'motor', 'not', 'rotating', 'happens', 'after', 'the', 'line', 'warms', 'up', 'm-07', 'al-102', 'โอ', 'อเ', 'เว', 'วอ', 'อร', 'ร์', '์โ', 'โห', 'หล', 'ลด', 'มอ', 'อเ', 'เต', 'ตอ', 'อร', 'ร์', '์ไ', 'ไม', 'ม่', '่ห', 'หม', 'มุ', 'ุน', 'เก', 'กิ', 'ิด', 'ดห', 'หล', 'ลั', 'ัง', 'งไ', 'ไล', 'ลน', 'น์', '์อ', 'อุ', 'ุ่', '่น', 'นเ', 'เค', 'คร', 'รื', 'ื่', '่อ', 'อง']::text[], 63, 'bge-m3@1');
